from typing import Optional

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

class Solution:
    def largestBSTSubtree(self, root: Optional[TreeNode]) -> int:
        max_size = 0

        def dfs(node):
            nonlocal max_size
            if not node:
                return True, 0, float("inf"), float("-inf")
            is_l, cnt_l, min_l, max_l = dfs(node.left)
            is_r, cnt_r, min_r, max_r = dfs(node.right)
            if is_l and is_r and max_l < node.val < min_r:
                curr_size = 1 + cnt_l + cnt_r
                max_size = max(max_size, curr_size)
                return True, curr_size, min(min_l, node.val), max(max_r, node.val)
            return False, max(cnt_l, cnt_r), 0, 0

        dfs(root)
        return max_size

class Solution {
    int maxSize = 0;
    struct Info {
        bool isBST;
        int size;
        int minVal;
        int maxVal;
    };
    Info dfs(TreeNode* node) {
        if (!node) return {true, 0, INT_MAX, INT_MIN};
        auto left = dfs(node->left);
        auto right = dfs(node->right);
        if (left.isBST && right.isBST && left.maxVal < node->val && node->val < right.minVal) {
            int sz = 1 + left.size + right.size;
            maxSize = max(maxSize, sz);
            int mn = (node->left ? left.minVal : node->val);
            int mx = (node->right ? right.maxVal : node->val);
            return {true, sz, mn, mx};
        }
        return {false, max(left.size, right.size), 0, 0};
    }
public:
    int largestBSTSubtree(TreeNode* root) {
        maxSize = 0;
        dfs(root);
        return maxSize;
    }
};

class Solution {
    private int maxSize = 0;

    static class Info {
        boolean isBST;
        int size;
        int minVal;
        int maxVal;
        Info(boolean isBST, int size, int minVal, int maxVal) {
            this.isBST = isBST;
            this.size = size;
            this.minVal = minVal;
            this.maxVal = maxVal;
        }
    }

    private Info dfs(TreeNode node) {
        if (node == null) return new Info(true, 0, Integer.MAX_VALUE, Integer.MIN_VALUE);
        Info left = dfs(node.left);
        Info right = dfs(node.right);
        if (left.isBST && right.isBST && left.maxVal < node.val && node.val < right.minVal) {
            int sz = 1 + left.size + right.size;
            maxSize = Math.max(maxSize, sz);
            int mn = (node.left != null ? left.minVal : node.val);
            int mx = (node.right != null ? right.maxVal : node.val);
            return new Info(true, sz, mn, mx);
        }
        return new Info(false, Math.max(left.size, right.size), 0, 0);
    }

    public int largestBSTSubtree(TreeNode root) {
        maxSize = 0;
        dfs(root);
        return maxSize;
    }
}

var largestBSTSubtree = function(root) {
    let maxSize = 0;

    function dfs(node) {
        if (!node) return [true, 0, Infinity, -Infinity];
        const [isL, cntL, minL, maxL] = dfs(node.left);
        const [isR, cntR, minR, maxR] = dfs(node.right);
        if (isL && isR && maxL < node.val && node.val < minR) {
            const sz = 1 + cntL + cntR;
            maxSize = Math.max(maxSize, sz);
            return [true, sz, Math.min(minL, node.val), Math.max(maxR, node.val)];
        }
        return [false, Math.max(cntL, cntR), 0, 0];
    }

    dfs(root);
    return maxSize;
};
